module array_top
   (clk,
    rst_n,
    start,
    M_size,
    K_size,
    N_size,
    addr_A,
    addr_B,
    data_A,
    data_B,
    we_C,
    addr_C,
    data_C,
    done);
  input clk;
  input rst_n;
  input start;
  input [15:0]M_size;
  input [15:0]K_size;
  input [15:0]N_size;
  output [31:0]addr_A;
  output [31:0]addr_B;
  input [31:0]data_A;
  input [31:0]data_B;
  output we_C;
  output [31:0]addr_C;
  output [31:0]data_C;
  output done;

  wire \<const0> ;
  wire [15:0]K_size;
  wire [15:0]M_size;
  wire [15:0]N_size;
  wire [31:0]act;
  wire [31:0]addr_A;
  wire [31:0]addr_B;
  wire [31:2]\^addr_C ;
  wire [3:0]clear_acc;
  wire clk;
  wire [31:0]data_A;
  wire [31:0]data_B;
  wire [31:0]data_C;
  wire done;
  wire [3:0]last_mac;
