  (* MARK_DEBUG *) wire [511:0]psum_out_matrix;
  wire rst_n;
  wire start;
  wire [3:0]vld;
  wire we_C;
  wire [31:0]weight;
  wire [31:30]NLW_u_ctrl_addr_C_UNCONNECTED;

initial begin
 $sdf_annotate("tb_array_top_auto_time_synth.sdf",,,,"tool_control");
end
  assign addr_C[31:2] = \^addr_C [31:2];
  assign addr_C[1] = \<const0> ;
  assign addr_C[0] = \<const0> ;
  GND GND
       (.G(\<const0> ));
  (* ADDR_WIDTH = "32" *) 
  (* ARRAY_SIZE = "4" *) 
  (* DONE = "6" *) 
  (* FLUSH = "3" *) 
  (* FLUSH_CYCLES = "12" *) 
  (* IDLE = "0" *) 
  (* KEEP_HIERARCHY = "SOFT" *) 
  (* LOAD = "1" *) 
  (* NEXT = "5" *) 
  (* RUN = "2" *) 
  (* TILE = "4" *) 
  (* TILE_SHIFT = "2" *) 
  (* WRITE_BACK = "4" *) 
  array_ctrl u_ctrl
       (.K_size(K_size),
        .M_size(M_size),
        .N_size(N_size),
        .act_in_left(act),
        .addr_A(addr_A),
        .addr_B(addr_B),
        .addr_C({NLW_u_ctrl_addr_C_UNCONNECTED[31:30],\^addr_C }),
        .clear_acc_left(clear_acc),
        .clk(clk),
        .data_A(data_A),
        .data_B(data_B),
        .data_C(data_C),
        .done(done),
        .last_mac_in_left(last_mac),
        .psum_in_matrix(psum_out_matrix),
        .rst_n(rst_n),
        .start(start),
        .valid_in_left(vld),
        .we_C(we_C),
        .weight_in_top(weight));
  (* ARRAY_SIZE = "4" *) 
  (* KEEP_HIERARCHY = "SOFT" *) 
  matmul_array u_matmul
       (.act_in_left(act),
